from playwright.sync_api import sync_playwright
exec(open('media.py').read().split("with sync_playwright()")[0])
with sync_playwright() as p:
    b = p.chromium.launch(); pg = b.new_context(viewport={"width":1500,"height":1000}).new_page(); errs=[]; pg.on("pageerror", lambda e: errs.append(str(e))); pg.on("console", lambda m: errs.append("console:"+m.text) if m.type=="error" and "ERR_TUNNEL" not in m.text and "adapters" not in m.text else None)
    pg.goto("http://localhost:4173/", wait_until="networkidle"); pg.wait_for_timeout(300)
    box = pg.locator("#draw").bounding_box(); cx, cy = box["x"]+box["width"]/2, box["y"]+box["height"]/2
    stroke(pg, "G-Pen", "#111111", 30, line(cx-150, cy-100, cx+150, cy+100), 5)
    pg.on("dialog", lambda d: (print("DIALOG:", d.message), d.accept()))
    pg.click("#side .rail button[title='Generate']"); pg.wait_for_timeout(800)
    print("health chip:", pg.evaluate("() => document.querySelector('#side .panel.active .chip').textContent"))
    pg.click("#side .panel.active button[title='Generate']"); pg.wait_for_timeout(600)
    print("jobs:", pg.evaluate("() => window.omni.ml.jobs.map(j => [j.status, j.error])"))
    print("mid:", pg.evaluate("() => document.querySelector('#side .panel.active .gen-job .mono').textContent"))
    pg.wait_for_timeout(1500)
    print("done:", pg.evaluate("() => document.querySelector('#side .panel.active .gen-job .mono').textContent"))
    pg.click("#side .panel.active button[title='Add as layer']"); pg.wait_for_timeout(600)
    print("layers:", pg.evaluate("() => window.omni.doc.drawing.layers.map(l => l.name + ':' + l.tiles.size)"), "meta:", pg.evaluate("() => JSON.stringify(window.omni.doc.drawing.layers.find(l => l.meta).meta).slice(0,120)"))
    print("undo labels:", pg.evaluate("() => window.omni.history.labels"))
    pg.screenshot(path="gen_panel.png")
    # inpaint with a wand selection, hires + tags
    pg.keyboard.press("w"); pg.evaluate("([x,y]) => { const c = document.querySelector('#draw'); const f = (t) => c.dispatchEvent(new PointerEvent(t, { pointerId: 44, pointerType: 'mouse', isPrimary: true, clientX: x, clientY: y, buttons: 1, bubbles: true })); f('pointerdown'); f('pointerup'); }", [cx, cy]); pg.wait_for_timeout(400)
    pg.click("#side .panel.active button[title='Fix this area']"); pg.click("#side .panel.active button.tag[title='1girl']"); pg.fill("#side .panel.active input[type=search]", "cel"); pg.wait_for_timeout(150); pg.click("#side .panel.active button.tag[title='cel shading']"); pg.fill("#side .panel.active input[type=search]", ""); pg.wait_for_timeout(200)
    pg.evaluate("() => { const cb = [...document.querySelectorAll('#side .panel.active input[type=checkbox]')].find(c => c.title === 'Hi-res fix'); cb.click(); }"); pg.wait_for_timeout(200)
    pg.click("#side .panel.active button[title='Generate']"); pg.wait_for_timeout(2200)
    j = pg.evaluate("() => { const j = window.omni.ml.jobs[0]; return [j.status, j.req.mode, !!j.req.mask, j.req.hiresFix, j.req.prompt.slice(0, 40), j.req.scheduler]; }")
    print("inpaint job:", j)
    print("presets shown:", pg.evaluate("() => [...document.querySelectorAll('#side .panel.active select')].map(s => s.options.length)"), "loras:", pg.evaluate("() => [...document.querySelectorAll('#side .panel.active input[type=checkbox]')].filter(c => c.title.startsWith('LoRA')).map(c => c.title)"))
    pg.click("#side .panel.active button[title='Tags from drawing']"); pg.wait_for_timeout(500); print("tags after tagger:", pg.evaluate("() => JSON.parse(localStorage.getItem('omni.ml')).tags"))
    pg.click("#side .panel.active button[title='Upscale 2×'] >> nth=0"); pg.wait_for_timeout(800); print("layers after upscale:", pg.evaluate("() => window.omni.doc.drawing.layers.map(l => l.name)"))
    # anime mode: render all frames
    pg.evaluate("() => { window.omni.setMode('anime'); }"); pg.wait_for_timeout(300); pg.click("button[title='New drawing at this frame']"); pg.wait_for_timeout(300)
    pg.click("#side .rail button[title='Generate']"); pg.wait_for_timeout(300); pg.click("#side .panel.active button[title='Colour my lines']")
    pg.click("#side .panel.active button[title='Render all frames']"); pg.wait_for_timeout(4500)
    print("frames:", pg.evaluate("() => window.omni.doc.frames.map(f => f.layers.map(l => l.name))"))
    pg.screenshot(path="gen_panel2.png", clip={"x": box["x"]+box["width"], "y": 0, "width": 1500-box["x"]-box["width"], "height": 1000})
    # mock provider too
    pg.select_option("#side .panel.active select >> nth=0", "mock"); pg.wait_for_timeout(300)
    pg.click("#side .panel.active button[title='Repaint this drawing']"); pg.click("#side .panel.active button[title='Generate']"); pg.wait_for_timeout(1800)
    print("mock:", pg.evaluate("() => document.querySelector('#side .panel.active .gen-job .mono').textContent"))
    pg.screenshot(path="gen_mock.png", clip={"x": box["x"]+box["width"], "y": 0, "width": 1500-box["x"]-box["width"], "height": 1000})
    print("errors:", errs); b.close()
